begin;
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000001','lots@example.test',now()),('00000000-0000-4000-8000-000000000002','outsider@example.test',now());
insert into auth.sessions(id,user_id) values('30000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001'),('30000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claim.session_id','30000000-0000-4000-8000-000000000001',true);
select public.register_portal_session('Lots fixture');
do $$ declare b uuid;br uuid;i uuid;s uuid;r uuid;req uuid:=gen_random_uuid();m uuid;expired uuid;early uuid;late uuid;unknown uuid;v_today date:=(statement_timestamp() at time zone 'America/Lima')::date;begin
 b:=public.create_initial_bakery('Lots bakery','Main');select id into br from public.branches where bakery_id=b;
 insert into public.ingredients(bakery_id,name,unit,reference_cost) values(b,'Harina','kg',2) returning id into i;
 insert into public.suppliers(bakery_id,name) values(b,'Supplier') returning id into s;
 perform public.record_lot_movement(b,br,i,gen_random_uuid(),'in',4,'Expired','EXPIRED',v_today-1,null);
 perform public.record_lot_movement(b,br,i,gen_random_uuid(),'in',6,'Late','LATE',v_today+20,null);
 perform public.receive_purchase(b,br,s,gen_random_uuid(),jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',3,'unit_cost',4,'lot_code','EARLY','expires_on',v_today+2)));
 perform public.record_stock_movement(b,br,i,gen_random_uuid(),'in',2,'Unknown expiry');
 select id into expired from public.stock_lots where lot_code='EXPIRED';
 select id into early from public.stock_lots where lot_code='EARLY';
 select id into late from public.stock_lots where lot_code='LATE';
 select id into unknown from public.stock_lots where lot_code is null;
 if (select quantity from public.stock_balances where ingredient_id=i)<>15 or (select quantity from public.usable_stock where ingredient_id=i)<>11 then raise exception 'Wrong available stock';end if;
 r:=public.create_recipe_version(b,'Pan',100,jsonb_build_array(jsonb_build_object('ingredient_id',i,'quantity',5)));
 perform public.complete_production(b,br,r,gen_random_uuid(),100);
 if (select quantity from public.stock_lots where id=early)<>0 or (select quantity from public.stock_lots where id=late)<>4 or (select quantity from public.stock_lots where id=expired)<>4 or (select quantity from public.stock_lots where id=unknown)<>2 then raise exception 'FEFO failed';end if;
 if (select count(*) from public.stock_lot_allocations)<>2 then raise exception 'Missing allocation trace';end if;
 begin perform public.record_stock_movement(b,br,i,gen_random_uuid(),'out',7,'Not enough usable');raise exception 'Expired stock consumed';exception when check_violation then null;end;
 if (select quantity from public.stock_balances where ingredient_id=i)<>10 then raise exception 'Failed withdrawal altered stock';end if;
 m:=public.record_lot_movement(b,br,i,req,'out',4,'Vencimiento',null,null,expired);
 if m<>public.record_lot_movement(b,br,i,req,'out',4,'Vencimiento',null,null,expired) then raise exception 'Waste retry failed';end if;
 if (select quantity from public.stock_balances where ingredient_id=i)<>6 or (select sum(quantity) from public.stock_lots where ingredient_id=i)<>6 then raise exception 'Waste balance mismatch';end if;
 if not exists(select 1 from public.stock_movements where id=m and movement_category='waste') then raise exception 'Waste not classified';end if;
 begin perform public.record_lot_movement(b,br,i,req,'out',4,'Vencimiento',null,null,late);raise exception 'Tampered retry accepted';exception when unique_violation then null;end;
 begin update public.stock_lots set quantity=0;raise exception 'Writable lot';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.session_id','30000000-0000-4000-8000-000000000002',true);
select public.register_portal_session('Outside');
do $$ begin if exists(select 1 from public.stock_lots) or exists(select 1 from public.usable_stock) or exists(select 1 from public.stock_lot_allocations) then raise exception 'Cross tenant lot leak';end if;end $$;
rollback;
